/* Generated from apps/video-inspect/src/pages/ProjectManagement/TaskManagement/QualityReport/style.module.less. DO NOT EDIT; run npm run inspect-lite:styles. */
.page {
  color-scheme: light;
  --page-bg: #f6f8fa;
  --ink: #0c0d0e;
  --muted: #737a87;
  --line: #dde2e9;
  --panel: #fff;
  --primary: #1664ff;
  --risk: #d7312a;
  --risk-soft: #fff0ef;
  --success: #2a814b;
  --radius: 12px;
  --shadow: 0 15px 35px -2px rgba(0, 0, 0, 0.05), 0 5px 15px rgba(0, 0, 0, 0.05);
  font-family: 'PingFang SC', 'Microsoft YaHei', Inter, system-ui, sans-serif;
  font-size: 14px;
  line-height: 1.6;
  height: 100vh;
  overflow: auto;
  min-width: 320px;
  color: var(--ink);
  background: var(--page-bg);
  scroll-behavior: smooth;
}
@media (prefers-reduced-motion: reduce) {
  .page *,
  .page *::before,
  .page *::after {
    scroll-behavior: auto;
    transition: none;
  }
}
.page h1,
.page h2,
.page h3,
.page strong,
.page b {
  font-weight: bold;
}
.page * {
  box-sizing: border-box;
}
.page {
  /* Keep content-analysis tabs aligned with the ecommerce review report. */
  /* Present risk fragments as the same open timeline used by review problem moments. */
}
.page button,
.page input {
  font: inherit;
}
.page button {
  color: inherit;
}
.page .topbar {
  position: sticky;
  z-index: 20;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  padding: 0 24px;
  border-bottom: 1px solid rgba(221, 226, 233, 0.8);
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(12px);
}
.page .brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 16px;
}
.page .brand strong {
  font-weight: 650;
}
.page .brand-mark {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  color: #fff;
  border-radius: 8px;
  background: linear-gradient(135deg, #3384ff, #014bde 52%, #a945fb);
  font-size: 12px;
  line-height: 1;
  font-weight: 800;
}
.page .local-badge,
.page .secure-chip {
  color: #315bba;
  border: 1px solid #d8e4ff;
  border-radius: 6px;
  background: #f4f7ff;
  padding: 4px 9px;
  font-size: 12px;
}
.page .shell {
  width: 100%;
  max-width: 1332px;
  margin: 16px auto 48px;
  padding: 0 16px;
}
.page .report-layout {
  display: grid;
  grid-template-columns: 420px minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}
.page .diagnosis-card {
  grid-column: 1 / -1;
}
.page .report-sidebar {
  position: sticky;
  top: 80px;
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
  min-width: 0;
}
.page .report-content {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.page .panel,
.page .task-card,
.page .data-card,
.page .evidence-section,
.page .rules-section,
.page .diagnosis-card {
  overflow: hidden;
  border: 1px solid rgba(221, 226, 233, 0.9);
  border-radius: var(--radius);
  background: var(--panel);
  box-shadow: var(--shadow);
}
.page .task-card {
  display: grid;
  grid-template-columns: 64px 1fr;
  gap: 12px;
  padding: 16px;
}
.page .task-cover {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  border-radius: 10px;
  background: linear-gradient(145deg, #dff4ff, #a9d9ff 52%, #b9b7ff);
}
.page .task-cover span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  color: #fff;
  border-radius: 50%;
  background: rgba(22, 100, 255, 0.7);
  font-size: 18px;
  font-weight: 700;
}
.page .task-heading {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
}
.page h1 {
  overflow: hidden;
  margin: 0;
  font-size: 14px;
  line-height: 1.45;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.page .task-meta {
  display: -webkit-box;
  overflow: hidden;
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.page .task-account {
  overflow: hidden;
  margin: 1px 0 0;
  color: #737a87;
  font-size: 11px;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.page .task-account[hidden] {
  display: none;
}
.page .task-account:not([hidden]) + .task-meta {
  margin-top: 1px;
}
.page .panel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 56px;
  padding: 0 16px;
  border-bottom: 1px solid var(--line);
}
.page .panel-title h2,
.page .section-title h2 {
  margin: 0;
  font-size: 17px;
  line-height: 1.4;
}
.page .panel-title > div {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.page .panel-title > div > span,
.page .section-title > span,
.page .section-title p {
  color: var(--muted);
  font-size: 12px;
}
.page .video-frame {
  position: relative;
  aspect-ratio: 1.6;
  background: #070a11;
}
.page video {
  display: block;
  width: 100%;
  height: 100%;
  background: #070a11;
}
.page .video-empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 18px;
  color: #c7ced8;
  background: rgba(7, 10, 17, 0.92);
  text-align: center;
  font-size: 13px;
}
.page .video-empty[hidden] {
  display: none;
}
.page .playhead-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px 14px 7px;
}
.page .playhead-row span:first-child {
  color: var(--primary);
  font: 700 12px ui-monospace, SFMono-Regular, Menlo, monospace;
}
.page .playhead-row span:last-child {
  overflow: hidden;
  color: var(--muted);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.page .timeline {
  position: relative;
  height: 56px;
  margin: 0 14px;
}
.page .timeline-track {
  position: absolute;
  top: 25px;
  right: 0;
  left: 0;
  height: 4px;
  border-radius: 99px;
  background: #e2e6ef;
}
.page .timeline-segment {
  position: absolute;
  z-index: 2;
  top: 23px;
  height: 8px;
  min-width: 4px;
  padding: 0;
  cursor: pointer;
  border: 0;
  border-radius: 3px;
  background: var(--segment-color, var(--risk));
}
.page .timeline-segment:focus-visible {
  outline: 2px solid #1664ff;
  outline-offset: 2px;
}
.page .playhead {
  position: absolute;
  z-index: 3;
  top: 14px;
  bottom: 13px;
  left: 0;
  width: 2px;
  pointer-events: none;
  background: #333847;
}
.page .playhead:before {
  position: absolute;
  top: -1px;
  left: -3px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #333847;
  content: '';
}
.page .timeline-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 15px;
  padding: 0 14px 15px;
  color: var(--muted);
  font-size: 11px;
}
.page .timeline-legend span {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
}
.page .timeline-legend i {
  width: 11px;
  height: 3px;
  flex: none;
  border-radius: 99px;
}
.page .timeline-legend span:not(:last-child) {
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.page .legend-risk {
  background: var(--risk);
}
.page .legend-playhead {
  background: #333847;
}
.page .diagnosis-card {
  padding: 28px 32px;
}
.page .diagnosis-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  color: var(--primary);
}
.page .diagnosis-banner span {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  color: #fff;
  border-radius: 8px;
  background: linear-gradient(135deg, #1664ff, #7857ff);
  font-size: 13px;
}
.page .diagnosis-banner h2 {
  margin: 0;
  color: var(--ink);
  font-size: 17px;
}
.page .diagnosis-summary {
  display: flex;
  align-items: center;
  min-height: 76px;
}
.page .diagnosis-title {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.page .diagnosis-title p {
  margin: 0;
  font-size: 20px;
  font-weight: 650;
  line-height: 1.45;
}
.page .diagnosis-title p em {
  color: var(--risk);
  font-style: normal;
}
.page .shield {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 25px;
  height: 29px;
  margin-top: 2px;
  color: #fff;
  clip-path: polygon(50% 0, 94% 16%, 87% 72%, 50% 100%, 13% 72%, 6% 16%);
  background: linear-gradient(#e7625b, var(--risk));
  font-weight: 800;
}
.page .data-card,
.page .evidence-section,
.page .rules-section {
  padding: 24px 28px;
}
.page .section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}
.page .section-title > div p {
  margin: 4px 0 0;
}
.page .section-kicker {
  color: #9397a5 !important;
  font-size: 10px !important;
  font-weight: 600;
  letter-spacing: 0.11em;
}
.page .summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}
.page .top-hit-rules {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}
.page .top-hit-rules .review-button {
  margin: 0;
  max-width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
}
.page .metric {
  position: relative;
  display: grid;
  min-height: 112px;
  padding: 16px 20px;
}
.page .metric:not(:last-child):after {
  position: absolute;
  top: 18px;
  right: 0;
  bottom: 18px;
  width: 1px;
  background: #eceef2;
  content: '';
}
.page .metric span {
  color: #4e5665;
  font-size: 14px;
}
.page .metric small {
  color: var(--muted);
  font-size: 12px;
}
.page .metric strong {
  align-self: center;
  font: 700 28px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: -0.04em;
}
.page .metric-risk strong {
  color: var(--risk);
}
.page .transcript-panel {
  min-height: 0;
}
.page .transcript-heading {
  padding: 0 20px;
}
.page .search {
  display: flex;
  align-items: center;
  gap: 7px;
  width: min(220px,40%);
  padding: 8px 11px;
  border: 1px solid #dfe3ea;
  border-radius: 7px;
  background: #f7f8fa;
}
.page .search span {
  color: var(--muted);
}
.page .search input {
  min-width: 0;
  width: 100%;
  color: var(--ink);
  outline: none;
  border: 0;
  background: transparent;
  font-size: 13px;
}
.page .search input::placeholder {
  color: #9a9eaa;
}
.page .notice {
  margin: 0;
  padding: 9px 20px;
  color: #8e503a;
  border-bottom: 1px solid #ffe1d7;
  background: #fff8f5;
  font-size: 12px;
}
.page .transcript-list {
  max-height: 420px;
  overflow: auto;
  scrollbar-color: #c8ccd6 transparent;
}
.page .transcript-row {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 16px;
  padding: 14px 20px;
  border-bottom: 1px solid #eef0f3;
  transition: background 0.15s ease;
}
.page .transcript-row:hover {
  background: #f7f9ff;
}
.page .transcript-row p {
  margin: 0;
  color: #343944;
  font-size: 14px;
  line-height: 1.65;
}
.page .timecode {
  height: fit-content;
  padding: 0;
  cursor: pointer;
  color: var(--primary);
  border: 0;
  background: transparent;
  font: 700 12px/1.65 ui-monospace, SFMono-Regular, Menlo, monospace;
  text-align: left;
}
.page .timecode:hover {
  text-decoration: underline;
}
.page mark {
  color: #3d348b;
  border-radius: 3px;
  background: #ebe8ff;
}
.page .evidence-list {
  display: grid;
  gap: 12px;
}
.page .evidence-card {
  display: grid;
  grid-template-columns: 42px 150px 1fr auto;
  align-items: center;
  gap: 17px;
  padding: 18px;
  border: 1px solid #e3e7ed;
  border-radius: 10px;
  background: #fff;
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}
.page .evidence-card:hover,
.page .evidence-card.active {
  border-color: #a9c3ff;
  box-shadow: 0 7px 20px rgba(22, 100, 255, 0.07);
}
.page .evidence-number {
  color: #adb3bd;
  font: 700 17px ui-monospace, SFMono-Regular, Menlo, monospace;
}
.page .evidence-copy {
  min-width: 0;
}
.page .evidence-copy h3 {
  margin: 7px 0 5px;
  font-size: 14px;
  font-weight: 600;
}
.page .evidence-copy p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
}
.page .evidence-tags {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}
.page .rule-tag,
.page .evidence-kind {
  display: inline-block;
  border-radius: 4px;
  padding: 3px 7px;
  font-size: 11px;
}
.page .rule-tag {
  color: var(--risk);
  background: var(--risk-soft);
}
.page .evidence-kind {
  color: #616a79;
  background: #f1f2f5;
}
.page .evidence-images {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(108px, 1fr));
  gap: 8px;
  max-width: 510px;
  margin-top: 11px;
}
.page .evidence-images a {
  display: block;
  overflow: hidden;
  aspect-ratio: 1.77777778;
  border: 1px solid #e5e7ec;
  border-radius: 7px;
  background: #f3f4f7;
}
.page .evidence-images img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.18s ease;
}
.page .evidence-images a:hover img {
  transform: scale(1.025);
}
.page .review-button {
  justify-self: end;
  cursor: pointer;
  padding: 8px 12px;
  color: var(--primary);
  border: 1px solid #ccdafe;
  border-radius: 6px;
  background: #f5f8ff;
  font-size: 12px;
}
.page .player-panel {
  scroll-margin-top: 80px;
}
.page .rule-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.page .rule-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 86px;
  overflow: hidden;
  padding: 16px;
  border: 1px solid #e3e7ed;
  border-radius: 10px;
  background: #fff;
}
.page .rule-status {
  min-width: max-content;
  padding: 4px 7px;
  flex: none;
  border-radius: 4px;
  font-size: 11px;
  white-space: nowrap;
  word-break: keep-all;
}
.page .rule-hit .rule-status {
  color: var(--risk);
  background: var(--risk-soft);
  font-weight: 700;
}
.page .rule-clear .rule-status {
  color: var(--success);
  background: #eaf8f3;
}
.page .rule-card h3 {
  margin: 0;
  font-size: 14px;
}
.page .empty-state {
